import { psiGeneratedAt, slimRuns } from "@/lib/psi-data";

export const revalidate = false;

/**
 * The unified PSI run table (psi-data/derived/runs.json, generated by
 * system/psi-ingest) without raw cells — what the Explorer queries in the
 * browser. Served as a static file so the site stays host-anywhere; the
 * Explorer's query code (lib/psi-query.ts) runs client-side over it.
 */
export function GET(): Response {
  return Response.json({ generated_at: psiGeneratedAt(), runs: slimRuns() });
}
